</td><td>{{ money(lineTotal(item)) }}</td></tr></tbody><tfoot><tr><th colspan="7">Total</th><th>{{ money(total) }}</th></tr></tfoot></table><div class="si-print-top"><section><h3>Terms &amp; Conditions</h3><p>{{ form.terms||'-' }}</p></section><section><h3>Notes</h3><p>{{ form.notes||'-' }}</p></section></div></div><aside><h3>SALES TRACKER</h3><table><thead><tr><th>Doc Type</th><th>Doc No</th><th>Total</th></tr></thead><tbody><tr v-if="form.sales_order"><td>Sales Order</td><td>{{ form.sales_order.order_no }}</td><td>{{ money(form.sales_order.total) }}</td></tr><tr><td>Sales Invoice</td><td>{{ form.invoice_no }}</td><td>{{ money(total) }}</td></tr><tr v-for="payment in form.payments" :key="payment.id"><td>Customer Payment</td><td>{{ payment.payment_no }}</td><td>{{ money(payment.amount) }}</td></tr></tbody></table><h3>Info</h3><p>Invoice Status: {{ form.status }}</p><p>Payment Status: {{ form.payment_status }}</p><p>Currency: {{ form.currency_code }}</p><p>Balance Due: {{ money(balance(form)) }}</p><h3>Last Update</h3><p>{{ dateLabel(form.updated_at) }}</p></aside></div></section>
      <section v-if="view==='detail'" class="si-print-references">
        <h3>Job &amp; Project References</h3>
        <div><span>Job Order No: {{ form.job_order_no||'-' }}</span><span>Job Order Date: {{ dateLabel(form.job_order_date) }}</span><span>Job Order Status: {{ form.job_order_status||'-' }}</span><span>Job Site: {{ form.job_site_name||'-' }}</span><span>Site Address: {{ form.job_site_address||'-' }}</span><span>Tax Registration: {{ form.tax_registration_no||'-' }}</span><span>Approved By: {{ form.approved_by||'-' }}</span></div>
      </section>
