</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { FileText, Search, Plus, ArrowLeft, RotateCcw, Eye, Pencil, Trash2, Printer, Mail, Save, FileDown, Copy, Send, Check, BadgeDollarSign, X, Clock, CircleCheck, Wallet, AlertCircle } from 'lucide-vue-next'
import AccountLayout from '../components/AccountLayout.vue'
import Field from '../components/PurchaseOrderField.vue'
import client from '../api/client'
import { authState } from '../store/auth'
import { today, money, dateLabel, roundMoney } from '../utils/purchaseOrders'
const route=useRoute()
const rows=ref([]),customers=ref([]),orders=ref([]),view=ref('list'),editing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),paymentOpen=ref(false),page=ref(1),perPage=ref(15),search=ref('')
const statuses=['Draft','Pending','Open','Rejected'],currencies=['USD','CAD','EUR','GBP','BDT'],channels=['Direct','Online','Referral','Partner'],shippingMethods=['Our Truck','Courier','Customer Pickup','Third Party']
const blankItem=()=>({name:'',description:'',uom:'PCS',quantity:1,unit_price:0,discount:0,tax_rate:0})
const blank=()=>({id:null,invoice_no:'',customer_id:null,customer_details:{},sales_order_id:null,sales_order:null,invoice_date:today(),due_date:'',delivery_date:'',customer_po_no:'',salesperson:'',department:'Sales',currency_code:'USD',exchange_rate:1,price_list:'Standard Price List',sales_channel:'Direct',delivery_location:'',shipping_method:'',tracking_no:'',shipping_terms:'',payment_terms:'',reference:'',job_order_no:'',job_order_date:'',job_order_status:'',job_site_name:'',job_site_address:'',tax_registration_no:'',approved_by:'',internal_notes:'',status:'Draft',payment_status:'Unpaid',subtotal:0,discount:0,sales_tax:0,total:0,paid:0,items:[],terms:'',notes:'',payment_information:'',payments:[]})
const form=ref(blank()),payment=ref({payment_no:'',payment_date:today(),amount:0,method:'',reference:''}),filters=ref({from:'',to:'',customer:'',status:'',payment:''})
const customer=computed(()=>form.value.customer_details||{})
const customerOrders=computed(()=>orders.value.filter(x=>Number(x.customer_id)===Number(form.value.customer_id)))
const filtered=computed(()=>rows.value.filter(x=>(!search.value||[x.invoice_no,x.customer_details?.name].join(' ').toLowerCase().includes(search.value.toLowerCase()))&&(!filters.value.from||x.invoice_date>=filters.value.from)&&(!filters.value.to||x.invoice_date<=filters.value.to)&&(!filters.value.customer||Number(x.customer_id)===Number(filters.value.customer))&&(!filters.value.status||x.status===filters.value.status)&&(!filters.value.payment||x.payment_status===filters.value.payment)))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage.value))),start=computed(()=>(page.value-1)*perPage.value),paged=computed(()=>filtered.value.slice(start.value,start.value+perPage.value))
const subtotal=computed(()=>roundMoney(form.value.items.reduce((sum,x)=>sum+Number(x.quantity||0)*Number(x.unit_price||0),0)))
const discount=computed(()=>roundMoney(form.value.items.reduce((sum,x)=>sum+Number(x.quantity||0)*Number(x.unit_price||0)*Number(x.discount||0)/100,0)))
const tax=computed(()=>roundMoney(form.value.items.reduce((sum,x)=>sum+Number(x.quantity||0)*Number(x.unit_price||0)*(1-Number(x.discount||0)/100)*Number(x.tax_rate||0)/100,0)))
const total=computed(()=>roundMoney(subtotal.value-discount.value+tax.value))
const availableCredit=computed(()=>Math.max(0,Number(customer.value.credit_limit||0)-Number(customer.value.balance||0)-total.value))
const canSubmit=computed(()=>form.value.id&&!editing.value&&['Draft','Rejected'].includes(form.value.status)),canApprove=computed(()=>form.value.id&&!editing.value&&form.value.status==='Pending'),canPay=computed(()=>form.value.id&&!editing.value&&form.value.status==='Open'&&balance(form.value)>0)
const metrics=computed(()=>[{label:'Total Invoices',count:rows.value.length,amount:rows.value.reduce((s,x)=>s+Number(x.total||0),0),icon:FileText,tone:''},{label:'Open',count:rows.value.filter(x=>x.status==='Open').length,amount:rows.value.filter(x=>x.status==='Open').reduce((s,x)=>s+Number(x.total||0),0),icon:Clock,tone:'amber'},{label:'Paid',count:rows.value.filter(x=>x.payment_status==='Paid').length,amount:rows.value.filter(x=>x.payment_status==='Paid').reduce((s,x)=>s+Number(x.paid||0),0),icon:CircleCheck,tone:'green'},{label:'Balance Due',count:rows.value.filter(x=>balance(x)>0).length,amount:rows.value.reduce((s,x)=>s+balance(x),0),icon:Wallet,tone:'red'}])
const company=computed(()=>({name:authState.user?.company_name||authState.user?.business_name||'Company Name',address:authState.user?.company_address||'',phone:authState.user?.contact_primary_phone||'',email:authState.user?.contact_business_email||authState.user?.email||'',website:authState.user?.website||''}))
watch(filtered,()=>{if(page.value>pages.value)page.value=pages.value})
function slug(x){return String(x||'').toLowerCase().replace(/\s+/g,'-')}
function balance(x){return Math.max(0,roundMoney(Number(x.id?x.total:total.value)-Number(x.paid||0)))}
function lineTotal(x){const base=Number(x.quantity||0)*Number(x.unit_price||0)*(1-Number(x.discount||0)/100);return roundMoney(base*(1+Number(x.tax_rate||0)/100))}
function apiError(e){return Object.values(e.response?.data?.errors||{})[0]?.[0]||e.response?.data?.message||e.message||'Request failed.'}
async function all(url){let pageNo=1,last=1,result=[];do{const{data}=await client.get(url,{params:{per_page:100,page:pageNo}});result.push(...(data.data?.data||[]));last=data.data?.last_page||1;pageNo++}while(pageNo<=last);return result}
async function load(){rows.value=await all('/sales-invoices')}
async function loadOptions(){const{data}=await client.get('/sales-invoices/options');customers.value=data.data.customers||[];orders.value=data.data.orders||[]}
function normalize(x){return{...blank(),...x,invoice_date:String(x.invoice_date||today()).slice(0,10),due_date:String(x.due_date||'').slice(0,10),delivery_date:String(x.delivery_date||'').slice(0,10),job_order_date:String(x.job_order_date||'').slice(0,10),items:(x.items||[]).map(i=>({...i})),payments:x.payments||[]}}
function startNew(){form.value=blank();view.value='detail';editing.value=true;error.value='';notice.value=''}
function back(){view.value='list';editing.value=false}
async function openInvoice(row){busy.value=true;try{const{data}=await client.get('/sales-invoices/'+row.id);form.value=normalize(data.data);view.value='detail';editing.value=false}catch(e){error.value=apiError(e)}finally{busy.value=false}}
async function cancel(){if(form.value.id)await openInvoice(form.value);else back()}
function applyCustomer(){form.value.customer_details=customers.value.find(x=>x.id===Number(form.value.customer_id))||{};form.value.sales_order_id=null;form.value.sales_order=null}
function applyOrder(){const order=orders.value.find(x=>x.id===Number(form.value.sales_order_id));if(!order)return;form.value.sales_order=order;form.value.customer_id=order.customer_id;form.value.customer_details=customers.value.find(x=>x.id===Number(order.customer_id))||order.customer_details||{};form.value.items=(order.items||[]).map(x=>({...x}));form.value.customer_po_no=order.customer_po_no||'';form.value.salesperson=order.salesperson||'';form.value.department=order.department||'Sales';form.value.currency_code=order.currency_code||'USD';form.value.delivery_location=order.delivery_location||'';form.value.shipping_method=order.shipping_method||'';form.value.shipping_terms=order.shipping_terms||'';form.value.payment_terms=order.payment_terms||'';form.value.terms=order.terms||''}
function addItem(){form.value.items.push(blankItem())}
function resetFilters(){filters.value={from:'',to:'',customer:'',status:'',payment:''};page.value=1}
async function saveInvoice(){error.value='';if(!form.value.customer_id||!form.value.items.length){error.value='Select a customer and add at least one item.';return}busy.value=true;try{const{data}=form.value.id?await client.put('/sales-invoices/'+form.value.id,form.value):await client.post('/sales-invoices',form.value);form.value=normalize(data.data);editing.value=false;notice.value='Sales invoice saved.';await load()}catch(e){error.value=apiError(e)}finally{busy.value=false}}
async function deleteInvoice(){if(!confirm('Delete '+form.value.invoice_no+'?'))return;busy.value=true;try{await client.delete('/sales-invoices/'+form.value.id);await load();back();notice.value='Sales invoice deleted.'}catch(e){error.value=apiError(e)}finally{busy.value=false}}
function duplicateInvoice(){form.value=normalize({...form.value,id:null,invoice_no:'',status:'Draft',paid:0,payment_status:'Unpaid',payments:[]});editing.value=true}
async function workflow(action){busy.value=true;try{const{data}=await client.post('/sales-invoices/'+form.value.id+'/workflow',{action});form.value=normalize(data.data);await load();notice.value='Invoice '+form.value.status.toLowerCase()+'.'}catch(e){error.value=apiError(e)}finally{busy.value=false}}
async function receivePayment(){busy.value=true;try{const{data}=await client.post('/sales-invoices/'+form.value.id+'/payments',payment.value);form.value=normalize(data.data);paymentOpen.value=false;payment.value={payment_no:'',payment_date:today(),amount:0,method:'',reference:''};await load();notice.value='Payment recorded.'}catch(e){error.value=apiError(e)}finally{busy.value=false}}
function printPage(){window.print()}
function savePdf(){printPage()}
function emailInvoice(){window.location.href='mailto:'+encodeURIComponent(customer.value.email||'')+'?subject='+encodeURIComponent('Sales Invoice '+(form.value.invoice_no||''))}
onMounted(async()=>{busy.value=true;try{await Promise.all([load(),loadOptions()]);if(route.query.sales_order_id){startNew();form.value.sales_order_id=Number(route.query.sales_order_id);applyOrder()}}catch(e){error.value=apiError(e)}finally{busy.value=false}})
</script>
