@media print{.si-print-references{display:block!important;margin-top:12px;font:11px Arial,sans-serif}.si-print-references h3{background:#0c248b;color:#fff;padding:5px}.si-print-references>div{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}}
</style>
